sources=[dict(id='nccp00216',title='NCCP Capecitabine Monotherapy',version='8',version_date='2025-01-27',published='2015-01-10',review='2030-01-27',url='https://healthservice.hse.ie/documents/6558/216_v8_Capecitabine.pdf',file='00216.pdf',sha256=sha(here/'00216.pdf'),pages=8,checked='2026-11-05',retrieved_utc='2026-11-05T19:51:00Z',retrieval_time_precision='minute',comparison='Identical PDF hash to pre-v36 retained source; source version unchanged',source_precedence='Primary regimen-specific schedule, eligibility, tests and modification tables'),dict(id='ema-xeloda',title='EMA Xeloda product information',url='https://www.ema.europa.eu/en/documents/product-information/xeloda-epar-product-information_en.pdf',retrieval_url='https://www.ema.europa.eu/en/documents/product-information/xeloda-epar-product-information_en.pdf?source=nccp-audit',file='ema-xeloda.pdf',sha256=sha(here/'ema-xeloda.pdf'),pages=50,checked='2026-11-05',retrieval='Fresh direct HTTPS PDF download succeeded after initial429; also independently opened with web retrieval',product_page='https://www.ema.europa.eu/en/medicines/human/EPAR/xeloda',product_page_last_updated='2025-05-02',source_precedence='Supplementary safety/contraindication/interaction source; explicit differences never silently override NCCP')]
